import networkx as nx
G = nx.Graph()
G.add_nodes_from(range(8))
G.add_edges_from([(0,4), (0,7), (2,4)])
while True:
    for u in range(8):
        for v in range(u+1, 8):
            if not G.has_edge(u, v) and len(list(G.neighbors(u))) < 4 and len(list(G.neighbors(v))) < 4:
                G.add_edge(u, v)
    if all(4 <= len(list(G.neighbors(u))) <= 4 for u in range(8)):
        break
print([(u, v) for u in range(8) for v in range(u+1, 8) if G.has_edge(u, v)])
